"""Extend dated administrative coverage to1900 without backdating mandates."""
import copy,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]/'public/data'
path=ROOT/'territorial-administrations.json'
d=json.loads(path.read_text(encoding='utf8'));d['coverageStart']='1900-01-01'
for r in d['records']:
    if r['start']=='1920-01-01' and r['id']!='south-west-africa-mandate':
        r.update(start='1916-11-03' if r['id']=='protected-QAT' else '1900-01-01',startIsCoverageBoundary=r['id']!='protected-QAT')
        r['note']=r['note'].replace('retroproyecta a 1920','retroproyecta a 1900')
        if r['start']=='1900-01-01':r['note']+=' El inicio1900 es un límite de cobertura documental, no comienzo de la administración.'
def add(record):
    if not any(r['id']==record['id'] for r in d['records']):d['records'].append(record)
add(dict(id='korea-japanese-protectorate',names=['Korea'],codes=['KEM'],admin='JPN',localKey='KEM',start='1905-11-17',end='1910-08-29',headOfStateOnly=False,label='Imperio coreano bajo protectorado japonés impuesto',note='El acuerdo de17/11/1905 privó a Corea de relaciones diplomáticas propias; la Residencia General amplió su intervención interior. Se conserva la autoridad imperial coreana y se separa del Gobierno japonés. No equivale todavía a la anexión colonial de1910 ni resuelve la controversia sobre la validez del tratado impuesto.',source='https://www.jacar.go.jp/english/exhibition/nichiro/19051117.htm'))
add(dict(id='korea-japanese-colonial-rule',names=['Korea'],codes=[],admin='JPN',localKey='',start='1910-08-29',end='1945-08-15',headOfStateOnly=False,label='Administración colonial japonesa de Corea',note='Tratado firmado22/8 y promulgado29/8/1910; la administración colonial sustituyó al Imperio coreano. El15/8/1945 corresponde a la rendición anunciada y liberación con posterior división de ocupaciones, no a una transferencia simultánea documentada en todas las localidades. No se heredan presidentes de las repúblicas creadas en1948.',source='https://contents.history.go.kr/front/nh/view.do?levelId=nh_047_0020_0010_0010'))
for key,name in [('TRV','Transvaal'),('ORF','Orange Free State')]:
    add(dict(id='boer-british-'+key,names=[name],codes=[key],admin='GBR',localKey=key,start='1902-05-31',end='1910-05-31',headOfStateOnly=False,label='Colonia británica posterior a la Paz de Vereeniging',note='La paz somete las antiguas repúblicas a la Corona; autogobierno colonial y posterior Unión de Sudáfrica son etapas distintas. Se conservan los titulares locales documentados y las autoridades estatales británicas; no es un censo completo de gobernadores.',source='https://www.nam.ac.uk/explore/boer-war'))
add(dict(id='morocco-french-protectorate',names=['Morocco'],codes=['MAR'],admin='FRA',localKey='MAR',start='1912-03-30',end='1956-03-02',headOfStateOnly=False,label='Sultanato bajo protectorado francés',note='El tratado de Fès conserva la institución del sultán y somete relaciones exteriores y reformas al protector. La zona española y Tánger tienen regímenes propios; esta relación se aplica al componente francés de la fuente, no atribuye toda la región a una administración homogénea.',source='https://archivesdiplomatiques.diplomatie.gouv.fr/ark%3A/14366/qsr9v8xd4jfn'))
add(dict(id='tonga-protected-monarchy',names=['Tonga'],codes=['TON'],admin='GBR',localKey='TON',start='1900-12-31',end='1970-06-04',startIsCoverageBoundary=True,headOfStateOnly=False,label='Monarquía tongana bajo acuerdo de protección británica',note='El tratado de1900 conservó la autonomía de Tonga pero delegó sus relaciones exteriores al Foreign Office. El extremo inicial es la ventana documental al cierre de1900, no día de firma. Los soberanos británicos se muestran exclusivamente como autoridades externas del Estado protector; no son reyes de Tonga. El acuerdo terminó4/6/1970.',source='https://history.state.gov/countries/tonga'))
add(dict(id='afghan-external-protection',names=['Afghanistan'],codes=['AFG'],admin='GBR',localKey='AFG',start='1900-01-01',end='1919-08-08',startIsCoverageBoundary=True,headOfStateOnly=False,label='Emirato afgano · control británico de relaciones exteriores hasta1919',note='Se conserva al emir como gobernante interno propio; las autoridades británicas son externas, no soberanos afganos. Amanullah repudió la tutela en febrero1919; el tratado de Rawalpindi8/8 reconoció la libertad de política exterior. El comienzo1900 es el límite de cobertura y el hito de agosto no niega la declaración anterior ni equivale a una anexión.',source='https://www.nam.ac.uk/explore/third-afghan-war-and-revolt-waziristan'))
add(dict(id='congo-transfer-1908',names=['Congo, Democratic Republic of (Zaire)'],codes=['COD'],admin='BEL',localKey='CFS',start='1908-11-15',end='1909-01-01',headOfStateOnly=False,label='Transferencia del Estado Libre al Congo Belga durante1908',note='Ventana de transición anual: conserva al soberano del Estado Libre hasta14/11 y añade las autoridades belgas desde la entrada en vigor de la ley15/11. El fin de esta ventana no termina la colonia; los años posteriores usan la relación cartográfica con Bélgica.',source='https://www.arch.be/index.php?a=2022-09-26-opnieuw-op-zijn-plaats-het-verdrag-tot-afstand-van-de-onafhankelijke-congostaat-aan-belgie&l=nl&m=nieuws&r=alle-nieuwsberichten'))
path.write_text(json.dumps(d,ensure_ascii=False,separators=(',',':'))+'\n',encoding='utf8',newline='\n')
print('Prepared1900 administrative coverage:',len(d['records']))
